/*
 * prog53_dfs_cycle
 *
 * Re‑implementation of the original program’s behaviour.
 *
 * Usage:
 *   ./prog53_dfs_cycle N u1 v1 u2 v2 ...
 *
 *   N          – number of vertices (0 < N ≤ 8)
 *   ui vi      – directed edge ui → vi   (0 ≤ ui,vi < N)
 *
 * Output (exactly one line):
 *   CYCLE          – a directed cycle exists
 *   ACYCLIC        – no directed cycle
 *   INVALID_INPUT  – malformed command‑line arguments
 *
 * The implementation follows the logic inferred from the decompiled,
 * heavily obfuscated binary (state‑machine style).  It reproduces the
 * same stdout for all possible inputs while being clean, readable,
 * and fully standards‑compliant.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXV 8                     /* maximum number of vertices (hard‑coded in binary) */

static int  adj[MAXV][MAXV];        /* adjacency matrix (directed) */
static int  color[MAXV];           /* 0 = unvisited, 1 = visiting, 2 = visited */
static bool found_cycle;           /* set to true when a cycle is discovered */

/* Depth‑first search that detects a directed cycle. */
static void dfs(int v)
{
    if (found_cycle)               /* early exit if a cycle is already known */
        return;

    color[v] = 1;                  /* mark as visiting */

    for (int w = 0; w < MAXV; ++w) {
        if (!adj[v][w])            /* no edge v→w */
            continue;

        if (color[w] == 0) {       /* tree edge */
            dfs(w);
            if (found_cycle)      /* propagate early exit */
                return;
        } else if (color[w] == 1) {/* back edge → cycle */
            found_cycle = true;
            return;
        }
        /* colour 2 (already finished) is ignored */
    }

    color[v] = 2;                  /* finished */
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* ---------- input validation -------------------------------------- */
    if (argc < 2) {                     /* need at least N */
        puts("INVALID_INPUT");
        return 0;
    }

    /* read number of vertices */
    char *endptr;
    long n_long = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_long <= 0 || n_long > MAXV) {
        puts("INVALID_INPUT");
        return 0;
    }
    int n = (int)n_long;

    /* the remaining arguments must come in pairs (u v) */
    if ((argc - 2) % 2 != 0) {
        puts("INVALID_INPUT");
        return 0;
    }

    int edge_cnt = (argc - 2) / 2;
    if (edge_cnt > MAXV) {               /* the original binary limits to 8 edges */
        puts("INVALID_INPUT");
        return 0;
    }

    /* clear adjacency matrix */
    memset(adj, 0, sizeof(adj));

    /* read edges */
    for (int i = 0; i < edge_cnt; ++i) {
        long u_long = strtol(argv[2 + 2 * i], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 0; }
        long v_long = strtol(argv[2 + 2 * i + 1], &endptr, 10);
        if (*endptr != '\0') { puts("INVALID_INPUT"); return 0; }

        if (u_long < 0 || u_long >= n || v_long < 0 || v_long >= n) {
            puts("INVALID_INPUT");
            return 0;
        }

        int u = (int)u_long;
        int v = (int)v_long;
        adj[u][v] = 1;                 /* directed edge u → v (duplicates are harmless) */
    }

    /* ---------- cycle detection --------------------------------------- */
    memset(color, 0, sizeof(color));
    found_cycle = false;

    for (int v = 0; v < n && !found_cycle; ++v) {
        if (color[v] == 0)
            dfs(v);
    }

    /* ---------- output ------------------------------------------------- */
    if (found_cycle)
        puts("CYCLE");
    else
        puts("ACYCLIC");

    return 0;
}
